    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO1_8_WAKE_LPI2C1_SDA,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO1_9_WAKE_LPI2C1_SCL,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_1_HSP_GPIO2_GPIO1,  IOMUXC_PIO_IBENA_MASK);
