/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitUSDHC0Pins
 * Description   : Routes PIO7_6..PIO7_11 to COMM_uSDHC0 CMD/CLK/DAT0-3 for
 *                 the on-board uSD slot. PIO6_11 is muxed as HSP_GPIO4_11
 *                 so software can drive VSELECT directly (3.3V / 1.8V
 *                 switching is handled via BOARD_SDCardIoVoltageControl in
 *                 sdmmc_config.c rather than by the USDHC controller).
 *
 * END ****************************************************************************************************************/
void BOARD_InitUSDHC0Pins(void)
{
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_6_COMM_uSDHC0_CMD,   IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_7_COMM_uSDHC0_CLK,   IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_8_COMM_uSDHC0_DAT0,  IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_9_COMM_uSDHC0_DAT1,  IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_10_COMM_uSDHC0_DAT2, IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO7_11_COMM_uSDHC0_DAT3, IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));

    /* VSELECT driven as a plain GPIO output (HSP_GPIO4_11). */
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO6_11_HSP_GPIO4_GPIO11, 0U);
}

