/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitENETPins
 * Description   : Configures the RGMII pins for the COMM_ENET MAC instance (board RJ45 labeled ETH1).
 *                 Each pad is muxed with its input buffer enabled (IOMUXC_PIO_IBENA_MASK) so the
 *                 RX and bidirectional MDIO/MDC lines can be read back by the controller. The MDIO
 *                 pad additionally enables an internal weak pull-up (IOMUXC_PIO_PULLENA, value 2 ==
 *                 "Enables pullup" per the PERI_IOMUXC.h PULLENA encoding) because MDIO is open-drain.
 *                 The PHY reset / interrupt pads are muxed as GPIO; the example's hardware_init.c
 *                 owns the GPIO direction and edge configuration.
 *
 * END ****************************************************************************************************************/
void BOARD_InitENETPins(void)
{
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_0_COMM_ENET_TX_CLK_IO, IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_1_COMM_ENET_TXD0,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_2_COMM_ENET_TXD1,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_3_COMM_ENET_TX_EN,     IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_4_COMM_ENET_RXD0,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_5_COMM_ENET_RXD1,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_6_COMM_ENET_MDIO,      IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_7_COMM_ENET_MDC,       IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_8_COMM_ENET_TXD2,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_9_COMM_ENET_TXD3,      IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_10_COMM_ENET_RX_CLK,   IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_11_COMM_ENET_RXD2,     IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_12_COMM_ENET_RXD3,     IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_13_COMM_ENET_RX_EN,    IOMUXC_PIO_IBENA_MASK);

    /* PHY reset on HSP__GPIO_0 pin 2 (PIO2_2): output, input buffer not needed. */
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO2_2_HSP_GPIO0_GPIO2, 0U);
    /* PHY interrupt on VBAT__GPIO_0 pin 2 (PIO0_2): input, input buffer enabled. */
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO0_2_VBAT_GPIO0_GPIO2, IOMUXC_PIO_IBENA_MASK);
}

/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitENETQOSPins
 * Description   : Configures the RGMII pins for the COMM_ENET_QOS MAC instance (board RJ45 labeled
 *                 ETH0). Same field semantics as BOARD_InitENETPins: every pad enables its input
 *                 buffer via IOMUXC_PIO_IBENA_MASK and MDIO additionally enables an internal weak
 *                 pull-up via IOMUXC_PIO_PULLENA (value 2 == "Enables pullup" per the PERI_IOMUXC.h
 *                 PULLENA encoding). PHY reset / interrupt pads are muxed as GPIO for the example.
 *
 * END ****************************************************************************************************************/
void BOARD_InitENETQOSPins(void)
{
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_14_COMM_ENET_QOS_TX_CLK_IO, IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_15_COMM_ENET_QOS_TX_DATA0,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_16_COMM_ENET_QOS_TX_DATA1,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_17_COMM_ENET_QOS_TX_EN,     IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_18_COMM_ENET_QOS_RX_DATA0,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_19_COMM_ENET_QOS_RX_DATA1,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_20_COMM_ENET_QOS_MDIO,      IOMUXC_PIO_IBENA_MASK | IOMUXC_PIO_PULLENA(2U));
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_21_COMM_ENET_QOS_MDC,       IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_22_COMM_ENET_QOS_TX_DATA2,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_23_COMM_ENET_QOS_TX_DATA3,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_24_COMM_ENET_QOS_RX_CLK,    IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_25_COMM_ENET_QOS_RX_DATA2,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_26_COMM_ENET_QOS_RX_DATA3,  IOMUXC_PIO_IBENA_MASK);
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO4_27_COMM_ENET_QOS_RXEN,     IOMUXC_PIO_IBENA_MASK);

    /* PHY reset on HSP__GPIO_0 pin 1 (PIO2_1): output, input buffer not needed. */
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO2_1_HSP_GPIO0_GPIO1, 0U);
    /* PHY interrupt on VBAT__GPIO_0 pin 1 (PIO0_1): input, input buffer enabled. */
    IOMUXC_SetPin_Mux_Config(IOMUXC_PIO0_1_VBAT_GPIO0_GPIO1, IOMUXC_PIO_IBENA_MASK);
}

